options.getOption:
// Every Sentinel-2 pass in the range as a bar as tall as its cloud cover, on
// the calendar. The bar in colour is the pass the map is drawing; the shaded
// band is the window of the map's time bar, and the passes inside it are the
// ones it chooses from (it draws the newest). The dashed line is the
// "Cloud cover ≤" cut, when there is one.
//
// Clicking a pass narrows the map's window to that pass alone, so the map draws
// it; clicking the pass already drawn opens the window to the whole range
// again, which draws the newest. The window lives in two hidden variables
// (FROM, TO) the map reads and writes (`timeSync: variables`): dragging the
// map's own time bar moves the band here too.
// The frame is the map's own query (time, scene_id, cloud_cover, raster_url),
// shared through the Dashboard datasource: no second catalogue search.
// @constants begin
const FROM = 'pass_from';
const TO = 'pass_to';
const CLOUD = 'cloud';
const DAY = 86400000;
const CONTEXT = 'rgba(128,128,128,0.35)';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;
const SHOWN = theme.visualization.getColorByName('orange');
const IN_WINDOW = theme.visualization.getColorByName('blue');

const frame = context.panel.data.series.find((f) => f.refId === 'A') ?? context.panel.data.series[0];
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const times = col('time').map(Number);
const ids = col('scene_id');
const clouds = col('cloud_cover').map((v) => (v == null ? null : Number(v)));
const order = times.map((_, i) => i).sort((a, b) => times[a] - times[b]);
const passes = order.map((i) => ({ time: times[i], id: ids[i], cloud: clouds[i] }));
const first = passes.length ? passes[0].time : null;
const last = passes.length ? passes[passes.length - 1].time : null;

const iso = (ms) => new Date(Math.round(ms)).toISOString();
const day = (ms) => new Date(ms).toISOString().slice(0, 10);

// The map's window, from the URL (what the map or a click just wrote), else
// from the variables. null until the map has published one.
const readWindow = () => {
  const search = new URLSearchParams(location.getLocation().search);
  const raw = (name) => search.get('var-' + name) ?? context.grafana.replaceVariables('${' + name + '}');
  const from = Date.parse(raw(FROM));
  const to = Date.parse(raw(TO));
  return Number.isFinite(from) && Number.isFinite(to) && from <= to ? { from, to } : null;
};
// The pass the map draws: the newest inside the window, the newest of all
// when there is no window yet, none when the window falls between passes.
const shownIn = (w) => {
  const inside = passes.filter((p) => !w || (p.time >= w.from && p.time <= w.to));
  return inside.length ? inside[inside.length - 1] : null;
};
const isWhole = (w) => !w || (w.from <= first && w.to >= last);

const publish = (from, to) => location.partial({ ['var-' + FROM]: iso(from), ['var-' + TO]: iso(to) }, true);

// A click anywhere in a pass's column picks it: the nearest pass to the
// pointer, within half a day either side of it on screen.
const onClick = (event) => {
  const at = [event.offsetX, event.offsetY];
  if (!passes.length || !chart.containPixel({ gridIndex: 0 }, at)) {
    return;
  }
  const t = chart.convertFromPixel({ gridIndex: 0 }, at)[0];
  const halfDayPx = Math.abs(chart.convertToPixel({ gridIndex: 0 }, [t + DAY / 2, 0])[0] - event.offsetX);
  let k = 0;
  passes.forEach((p, i) => {
    if (Math.abs(p.time - t) < Math.abs(passes[k].time - t)) k = i;
  });
  const px = chart.convertToPixel({ gridIndex: 0 }, [passes[k].time, 0])[0];
  if (Math.abs(px - event.offsetX) > Math.max(halfDayPx, 6)) {
    return;
  }
  const w = readWindow();
  const shown = shownIn(w);
  if (shown && shown.time === passes[k].time && !isWhole(w)) {
    publish(first, last);
    return;
  }
  // From halfway to the pass before to halfway to the pass after: the window
  // holds this pass and no other, and stays inside the data's own range.
  const from = k === 0 ? passes[k].time : (passes[k - 1].time + passes[k].time) / 2;
  const to = k === passes.length - 1 ? passes[k].time : (passes[k].time + passes[k + 1].time) / 2;
  publish(from, to);
};
const zr = chart.getZr();
zr.on('click', onClick);

const cut = Number(context.grafana.replaceVariables('${' + CLOUD + '}'));

const build = (w) => {
  const shown = shownIn(w);
  const inside = (p) => !w || (p.time >= w.from && p.time <= w.to);
  return {
    animation: false,
    backgroundColor: 'transparent',
    grid: { left: 8, right: 16, top: 30, bottom: 8, containLabel: true },
    tooltip: {
      trigger: 'item',
      formatter: (p) => {
        const pass = passes[p.dataIndex];
        const state = shown && pass.time === shown.time ? 'on the map · click to go back to the newest' : 'click to draw it';
        return `<b>${day(pass.time)}</b> ${new Date(pass.time).toISOString().slice(11, 16)} UTC<br/>${pass.id}<br/>Cloud cover: <b>${pass.cloud == null ? 'unknown' : pass.cloud.toFixed(1) + ' %'}</b><br/><span style="color:${muted}">${state}</span>`;
      },
    },
    xAxis: {
      type: 'time',
      min: first == null ? undefined : first - 2 * DAY,
      max: last == null ? undefined : last + 2 * DAY,
      axisLabel: { color: muted, hideOverlap: true },
      axisLine: { lineStyle: { color: muted } },
      splitLine: { show: false },
    },
    yAxis: {
      type: 'value',
      name: 'cloud %',
      min: 0,
      max: 100,
      interval: 50,
      nameTextStyle: { color: muted },
      axisLabel: { color: muted },
      splitLine: { lineStyle: { opacity: 0.15 } },
    },
    series: [
      {
        type: 'bar',
        name: 'Passes',
        barWidth: 7,
        barMinHeight: 3,
        data: passes.map((p) => ({
          value: [p.time, p.cloud ?? 0],
          itemStyle: {
            color: shown && p.time === shown.time ? SHOWN : inside(p) ? IN_WINDOW : CONTEXT,
            borderRadius: [2, 2, 0, 0],
          },
          label:
            shown && p.time === shown.time
              ? { show: true, position: 'top', color: text, fontSize: 11, formatter: () => day(p.time) }
              : { show: false },
        })),
        markArea:
          w && !isWhole(w)
            ? {
                silent: true,
                itemStyle: { color: 'rgba(128,128,128,0.12)', borderColor: muted, borderWidth: 1, borderType: 'dashed' },
                data: [[{ xAxis: w.from }, { xAxis: w.to }]],
              }
            : { data: [] },
        markLine:
          cut < 100
            ? {
                silent: true,
                symbol: 'none',
                label: { formatter: `cloud ≤ ${cut} %`, color: muted, fontSize: 10, position: 'insideEndTop' },
                lineStyle: { type: 'dashed', color: muted },
                data: [{ yAxis: cut }],
              }
            : { data: [] },
      },
    ],
  };
};

// The map writes its window as it is dragged; a click writes it here. Neither
// re-runs this panel's query, so the band and the colours are redrawn from
// the URL.
let drawn = JSON.stringify(readWindow());
const stop = location.getHistory().listen(() => {
  const w = readWindow();
  const key = JSON.stringify(w);
  if (key !== drawn && !chart.isDisposed()) {
    drawn = key;
    chart.setOption(build(w), { replaceMerge: ['series'] });
  }
});

return {
  version: 2,
  option: build(readWindow()),
  unsubscribe: () => {
    stop();
    zr.off('click', onClick);
  },
};

